<?php
declare(strict_types=1);
$portal_mode=true;
require_once __DIR__.'/auth/auth.php';
check_user_login();
require_once __DIR__.'/includes/useful-files-common.php';
$page_title='فایل‌های کاربردی';
$db=neal_useful_files_db();
$departments=neal_useful_files_departments($db);
$q=trim((string)($_GET['q']??''));
$department=trim((string)($_GET['department']??''));
if(!in_array($department,$departments,true))$department='';
$sql='SELECT id,title,description,department,original_name,mime_type,file_size,created_at FROM useful_files WHERE is_active=1';
$args=[];
if($q!==''){$sql.=' AND (title LIKE ? OR description LIKE ? OR original_name LIKE ?)';$like='%'.$q.'%';array_push($args,$like,$like,$like);}
if($department!==''){$sql.=' AND department=?';$args[]=$department;}
$sql.=' ORDER BY department COLLATE NOCASE,sort_order,title COLLATE NOCASE,id DESC';
$s=$db->prepare($sql);$s->execute($args);$items=$s->fetchAll();
function ufl_size($n){$n=(int)$n;if($n>=1048576)return number_format($n/1048576,2).' مگابایت';if($n>=1024)return number_format($n/1024).' کیلوبایت';return $n.' بایت';}
?>
