<div class="ufl-grid"><?php if($items):foreach($items as $item):$ext=strtolower(pathinfo((string)$item['original_name'],PATHINFO_EXTENSION));$icon=['pdf'=>'📕','doc'=>'📝','docx'=>'📝','xls'=>'📊','xlsx'=>'📊','ppt'=>'📽️','pptx'=>'📽️','jpg'=>'🖼️','jpeg'=>'🖼️','png'=>'🖼️','gif'=>'🖼️','webp'=>'🖼️','txt'=>'📄','csv'=>'📊'][$ext]??'📄';?><article class="ufl-card"><div class="ufl-card-top"><span class="ufl-icon"><?php echo $icon;?></span><div><h2><?php echo neal_uf_h($item['title']);?></h2><div class="ufl-filename"><?php echo neal_uf_h($item['original_name']);?></div></div></div><p class="ufl-desc"><?php echo neal_uf_h($item['description']?:'توضیحی برای این فایل ثبت نشده است.');?></p><div class="ufl-meta"><span class="ufl-dep"><?php echo neal_uf_h($item['department']);?></span><span class="ufl-size"><?php echo ufl_size($item['file_size']);?></span></div><a class="ufl-btn ufl-download" href="useful-file-download.php?id=<?php echo (int)$item['id'];?>">⬇ دریافت فایل</a></article><?php endforeach;else:?><div class="ufl-empty"><b>🔎</b><strong>فایلی با این مشخصات پیدا نشد</strong><p>عبارت جست‌وجو را تغییر دهید یا گزینه «همه دپارتمان‌ها» را انتخاب کنید.</p></div><?php endif;?></div></div>
